  "required": [
    "what",
    "why",
    "impact",
    "prediction",
    "recommended_action_ids",
    "sources"
  ],
  "properties": {
    "what": {
      "type": "string",
      "description": "One sentence naming the hazard, the asset and the zone."
    },
    "why": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Each corroborating reading, quoting the actual value and its threshold."
    },
    "impact": {
      "type": "string",
      "description": "Who and what is at risk, with the worker count."
    },
    "prediction": {
      "type": "string",
      "description": "What happens without intervention. Phrase as a risk, never as a certainty."
    },
    "recommended_action_ids": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Ids copied EXACTLY from allowed_actions. Never invent an id."
    },
    "sources": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "document": {
            "type": "string"
          },
          "section": {
            "type": "string"
          }
        }
      },
      "description": "Procedure sections actually retrieved, e.g. SOP-M04 \u00a74.2."
    }
  }
}

